<script setup>
import {ref,reactive,onMounted,onUnmounted} from 'vue';
import Market from './components/Market.vue';import ItemEditor from './components/ItemEditor.vue';import Orders from './components/Orders.vue';import Modal from './components/Modal.vue';
import {createClient,StaleResponse} from './lib/client';import {validatePassword,isActive,labels} from './lib/rules';import {ManagementPage} from './integration/management';
const user=ref(null),tab=ref('market'),busy=ref(false),feedback=ref('欢迎来到校园循环。'),failed=ref(false);
const items=ref([]),mine=ref([]),orders=ref([]),verifications=ref([]),inbox=ref([]),notices=ref([]),messages=ref([]),detail=ref(null),dialog=ref(null),chat=ref(null),messageText=ref('');
const query=reactive({q:'',category:''}),page=ref(1),register=ref(false),auth=reactive({username:'',password:'',nickname:''});
const blankItem=()=>({id:'',version:1,title:'',category:'教材书籍',description:'',price:'',image_id:''});
const itemForm=reactive(blankItem()),verifyForm=reactive({real_name:'',student_no:'',asset_id:''});const actionForm=reactive({reason:'',declared:false});
let searchSeq=0,chatSeq=0,loadSeq=0;
function clearPrivate(){mine.value=[];orders.value=[];verifications.value=[];inbox.value=[];notices.value=[];messages.value=[];detail.value=null;dialog.value=null;chat.value=null;messageText.value='';Object.assign(itemForm,blankItem());Object.assign(verifyForm,{real_name:'',student_no:'',asset_id:''});Object.assign(auth,{username:'',password:'',nickname:''});Object.assign(actionForm,{reason:'',declared:false});chatSeq++;loadSeq++;tab.value='market';}
const client=createClient({base:import.meta.env.VITE_API_BASE||'/api',onIdentityChange:clearPrivate});
function say(t,error=false){feedback.value=t;failed.value=error;}
async function syncIdentity(){const me=await client.request('/me');client.identity(me.user,me.csrf);user.value=me.user;return me.user;}
async function run(fn){if(busy.value)return;busy.value=true;try{await fn();}catch(e){if(!(e instanceof StaleResponse)){if(e.status===401||e.status===403){try{await syncIdentity();}catch{client.invalidate();user.value=null;}}say(e.message,true);}}finally{busy.value=false;}}
async function market(){const seq=++searchSeq;const data=await client.request('/items?'+new URLSearchParams({...query,page:page.value}));if(seq===searchSeq)items.value=data;}
async function loadPrivate(){if(!user.value)return;const seq=++loadSeq;const rows=await Promise.all(['/items/mine','/orders','/verifications','/inbox','/notifications'].map(p=>client.request(p)));if(seq!==loadSeq)return;[mine.value,orders.value,verifications.value,inbox.value,notices.value]=rows;}
async function refresh(){await syncIdentity();await Promise.all([market(),loadPrivate()]);}
async function refreshAfterSave(message){
 say(message);
 try{await Promise.all([market(),loadPrivate()]);}
 catch(e){if(e instanceof StaleResponse)throw e;say(message+' 列表刷新失败，请刷新查看，勿重复提交。',true);}
}

async function navigate(next){if(next!=='market'&&!user.value){dialog.value={type:'auth'};return;}tab.value=next;await run(async()=>{await syncIdentity();if(user.value||next==='market')await Promise.all([market(),loadPrivate()]);});}
async function authenticate(){await run(async()=>{if(register.value&&!validatePassword(auth.password))throw new Error('密码至少8个字符、UTF-8不超过72字节且不能全为空白。');const data=await client.request('/auth/'+(register.value?'register':'login'),{method:'POST',body:{...auth}});client.identity(data.user,data.csrf);user.value=data.user;dialog.value=null;auth.password='';await refreshAfterSave('登录成功，欢迎 '+user.value.nickname);});}
async function logout(){await run(async()=>{try{await client.request('/auth/logout',{method:'POST',body:{}});}finally{client.invalidate();user.value=null;}await syncIdentity();await market();say('已退出，私人草稿和页面已清理。');});}
function newItem(){if(!user.value){dialog.value={type:'auth'};return;}Object.assign(itemForm,blankItem());tab.value='publish';}
function editItem(i){Object.assign(itemForm,i);tab.value='publish';}
async function upload(event,kind,target,key){const file=event.target.files[0];if(!file)return;await run(async()=>{if(!['image/png','image/jpeg'].includes(file.type)||file.size>5*1024*1024)throw new Error('请选择5MB以内的JPEG或PNG图片。');const form=new FormData();form.append('file',file);form.append('kind',kind);const data=await client.request('/assets',{method:'POST',body:form});target[key]=data.id;say('图片上传成功。');});}
async function publish(){await run(async()=>{const {id,version,title,category,description,price,image_id}=itemForm;const body={title,category,description,price:String(price),image_id};if(id)body.version=version;await client.command(id?'/items/'+id:'/items',id?'PUT':'POST',body);Object.assign(itemForm,blankItem());tab.value='mine';await refreshAfterSave('已提交当前版本审核。');});}
async function verify(){await run(async()=>{await client.request('/verifications',{method:'POST',body:{...verifyForm}});Object.assign(verifyForm,{real_name:'',student_no:'',asset_id:''});await refreshAfterSave('认证已提交，请查看审核结果。');});}
function buy(i){if(!user.value){dialog.value={type:'auth'};return;}Object.assign(actionForm,{reason:'',declared:false});dialog.value={type:'buy',item:i};}
function orderAction(o,action){Object.assign(actionForm,{reason:'',declared:false});dialog.value={type:'action',order:o,action};}
function withdraw(i){Object.assign(actionForm,{reason:'',declared:false});dialog.value={type:'withdraw',item:i};}
async function submitAction(){await run(async()=>{const current=dialog.value;if(current.type==='buy'){if(!actionForm.declared)throw new Error('请核对物品和价格并主动确认。');await client.command('/orders','POST',{item_id:current.item.id,version:current.item.version});}
 else if(current.type==='withdraw'){if(!actionForm.declared)throw new Error('请主动确认撤下。');await client.request('/items/'+current.item.id+'/withdraw',{method:'POST',body:{}});}
 else {const a=current.action;const body={};if(['reject','deliver','cancel'].includes(a)){if(!actionForm.reason.trim())throw new Error('请填写原因或交付说明。');body.reason=actionForm.reason;}if(['deliver','confirm','cancel'].includes(a)){if(!actionForm.declared)throw new Error('请核实事实后主动勾选声明。');body.declared=true;}await client.command('/orders/'+current.order.id+'/'+a,'POST',body);}
 dialog.value=null;await refreshAfterSave('操作已保存，请查看当前结果。');});}
async function showDetails(o){await run(async()=>{detail.value=await client.request('/orders/'+o.id+'/details');});}
function openItemChat(i){openChat('ITEM',i.id,'',i.title,false);}
function openOrderChat(o){openChat('ORDER',o.id,'',o.title,!isActive(o));}
async function openChat(type,id,peer='',title='交易沟通',readonly=false){if(!user.value){dialog.value={type:'auth'};return;}chat.value={type,object:id,peer,title,readonly};messages.value=[];messageText.value='';await run(loadMessages);}
async function loadMessages(){const current=chat.value;if(!current)return;const seq=++chatSeq;
 if(current.type==='ORDER'){const d=await client.request('/orders/'+current.object+'/details');if(chat.value!==current)return;current.readonly=!isActive(d.order);}
 const data=await client.request('/messages?'+new URLSearchParams({type:current.type,object:current.object,peer:current.peer}));if(chat.value===current&&seq===chatSeq)messages.value=data;
}
async function send(){await run(async()=>{const current=chat.value;if(!current||current.readonly)throw new Error('订单已结束，会话只读。');await client.request('/messages?'+new URLSearchParams({type:current.type,object:current.object,peer:current.peer}),{method:'POST',body:{content:messageText.value}});messageText.value='';await loadMessages();});}
let poll,channel;
async function checkSession(){if(busy.value)return;try{const previousEpoch=client.epoch;await syncIdentity();if(previousEpoch!==client.epoch)await Promise.all([market(),loadPrivate()]);if(chat.value)await loadMessages();}catch(e){if(e.status===401){client.invalidate();user.value=null;}else if(!(e instanceof StaleResponse))say(e.message,true);}}
function focus(){checkSession();}
onMounted(async()=>{await run(refresh);poll=setInterval(checkSession,5000);window.addEventListener('focus',focus);if('BroadcastChannel' in window){channel=new BroadcastChannel('campus-session');channel.onmessage=()=>checkSession();}});
onUnmounted(()=>{clearInterval(poll);window.removeEventListener('focus',focus);channel?.close();client.invalidate();});
</script>
<template>
 <header><a class="brand" href="#" @click.prevent="navigate('market')"><span class="mark">循</span><span><strong>校园循环</strong><small>校园二手交易与物品流转平台</small></span></a><div class="identity"><template v-if="user"><span>{{user.nickname}} · {{user.verified?'已认证':'未认证'}}{{user.restricted?' · 账户受限':''}}</span><button :disabled="busy" @click="logout">退出登录</button></template><button v-else @click="dialog={type:'auth'}">登录 / 注册</button></div></header>
 <div class="notice">校内交接 · 线下结算 · 交付登记后仍须买方本人确认</div>
 <main><nav aria-label="主要导航"><button v-for="[id,label] in [['market','发现物品'],['mine','我的发布'],['orders','我的订单'],['messages','消息通知'],['account','个人中心']]" :key="id" :class="{active:tab===id}" @click="navigate(id)">{{label}}</button><button v-if="user?.role==='ADMIN'" @click="navigate('admin')">管理台</button><button class="primary" @click="newItem">＋ 发布闲置</button></nav>
 <div id="feedback" :class="{error:failed}" role="status" aria-live="polite"><span>{{busy?'正在处理，请稍候…':feedback}}</span><button :disabled="busy" @click="run(refresh)">刷新</button></div>
 <Market v-if="tab==='market'" :items="items" :query="query" :page="page" :busy="busy" @search="page=1;run(market)" @page="page+=$event;run(market)" @buy="buy" @chat="openItemChat"/>
 <section v-if="tab==='mine'"><h1>我的发布</h1><div class="grid"><article v-for="i in mine" :key="i.id" class="card"><span class="tag">{{i.status}}{{i.hidden?' · 已隐藏':''}}</span><h2>{{i.title}}</h2><p>¥ {{Number(i.price).toFixed(2)}} · 版本 {{i.version}}</p><p>{{i.reason||'暂无审核说明'}}</p><div class="actions"><button v-if="!user.restricted&&['在售','待审','审核退回','已撤下'].includes(i.status)" @click="editItem(i)">修改 / 重提</button><button v-if="!user.restricted&&['在售','待审','审核退回'].includes(i.status)" @click="withdraw(i)">撤下</button></div></article></div><p class="empty" v-if="!mine.length">还没有发布物品。</p></section>
 <ItemEditor v-if="tab==='publish'" :key="client.epoch" :form="itemForm" :busy="busy" @save="publish" @upload="upload($event,'ITEM',itemForm,'image_id')" @back="navigate('mine')"/>
 <Orders v-if="tab==='orders'" :orders="orders" :user="user" :busy="busy" @action="orderAction" @detail="showDetails" @chat="openOrderChat"/>
 <section v-if="tab==='account'&&user"><h1>个人中心</h1><p>{{user.nickname}} · {{user.verified?'认证通过':'认证未通过'}}</p><form v-if="!user.verified&&!user.restricted" class="card form" @submit.prevent="verify"><h2>校园身份认证</h2><label>真实姓名<input v-model="verifyForm.real_name" required maxlength="50"></label><label>学号<input v-model="verifyForm.student_no" required maxlength="50"></label><label>认证材料<input type="file" accept="image/png,image/jpeg" @change="upload($event,'VERIFY',verifyForm,'asset_id')"></label><p v-if="verifyForm.asset_id">材料已上传，仅本人及授权审核人员可见。</p><button :disabled="busy||!verifyForm.asset_id||verifications.some(v=>v.status==='待审')">提交认证</button></form><article v-for="v in verifications" :key="v.id" class="card"><h2>认证 · {{v.status}}</h2><p>{{v.reason||'等待审核'}}</p><small>{{v.created_at}}</small></article><p>认证退回后可修改材料重新提交。凭据找回不属于本轮范围。</p></section>
 <section v-if="tab==='messages'"><h1>消息与通知</h1><div class="grid"><div><h2>我的会话</h2><article v-for="c in inbox" :key="c.context_type+c.context_id+c.peer_id" class="card"><p>{{c.context_type==='ORDER'?'订单沟通':'物品咨询'}} · {{c.context_id}}</p><button @click="openChat(c.context_type,c.context_id,c.peer_id)">打开会话</button></article><p v-if="!inbox.length" class="empty">暂无会话，从物品或订单发起沟通。</p></div><div><h2>站内通知</h2><article v-for="n in notices" :key="n.id" class="card"><p>{{n.content}}</p><small>{{n.created_at}}</small></article><p v-if="!notices.length" class="empty">暂无通知。</p></div></div></section>
 <section v-if="tab==='admin'&&user?.role==='ADMIN'"><component v-if="ManagementPage" :is="ManagementPage" :user="user" :client="client" @changed="run(refresh)"/><div v-else class="empty"><h1>管理页面待 C 接入</h1><p>用户端已预留集成入口；认证、物品审核页面由C提供。此处不模拟审核成功。</p></div></section>
 <footer>校园循环 · 款项由双方线下结算，平台记录交易与治理过程。<br>公开资料不包含真实姓名、学号、认证材料或联系方式。</footer></main>
 <Modal v-if="dialog" :title="dialog.type==='auth'?(register?'注册校园账户':'欢迎回到校园循环'):dialog.type==='buy'?'确认下单':dialog.type==='withdraw'?'撤下物品':labels[dialog.action]" @close="!busy&&(dialog=null)">
  <form v-if="dialog.type==='auth'" class="form" @submit.prevent="authenticate"><label>账号<input v-model="auth.username" required autocomplete="username" pattern="[A-Za-z0-9_]{3,40}"></label><label>密码<input v-model="auth.password" required type="password" :autocomplete="register?'new-password':'current-password'"></label><label v-if="register">昵称<input v-model="auth.nickname" required maxlength="30"></label><p class="inline-error" v-if="failed">{{feedback}}</p><div class="actions"><button class="primary" :disabled="busy">{{register?'注册':'登录'}}</button><button type="button" @click="register=!register;auth.password=''">{{register?'已有账号':'注册新账号'}}</button></div></form>
  <form v-else class="form" @submit.prevent="submitAction"><template v-if="dialog.type==='buy'"><h3>{{dialog.item.title}} · ¥ {{dialog.item.price}}</h3><p>下单将预占物品，线下结算。物品版本变化时需重新核对。</p><label class="check"><input type="checkbox" v-model="actionForm.declared" required>我已核对物品描述和价格，确认购买</label></template><label v-else-if="dialog.type==='withdraw'" class="check"><input type="checkbox" v-model="actionForm.declared" required>确认撤下本人物品并保留历史</label><template v-else><label v-if="['reject','deliver','cancel'].includes(dialog.action)">{{dialog.action==='deliver'?'交付登记（时间、地点、说明）':'原因'}}<textarea v-model="actionForm.reason" required maxlength="1000" rows="4"/></label><label v-if="['deliver','confirm','cancel'].includes(dialog.action)" class="check"><input type="checkbox" v-model="actionForm.declared" required>{{dialog.action==='deliver'?'我确认已经实际交付':dialog.action==='confirm'?'我本人已经收到物品':'我声明尚未实际交付；已交付或有分歧不得普通取消'}}</label><p v-if="dialog.action==='cancel'">如果实际已经交付，请先与对方核查并走争议处理，不能虚假声明取消。</p></template><p v-if="failed" class="inline-error">{{feedback}}</p><button class="primary" :disabled="busy">确认提交</button></form>
 </Modal>
 <Modal v-if="detail" title="订单快照与交付记录" @close="detail=null"><h3>{{detail.order?.title}}</h3><p class="description">{{detail.order?.description}}</p><p>阶段：{{detail.order?.stage}} · 快照价格：¥ {{detail.order?.price}}</p><template v-if="detail.delivery"><h3>交付登记</h3><p>{{detail.delivery.actor_name||detail.delivery.actor_id}} · {{detail.delivery.created_at}}</p><p class="description">{{detail.delivery.note}}</p></template><p v-else>尚无交付登记，不能据此认定已收到。</p></Modal>
 <Modal v-if="chat" :title="chat.title" @close="chat=null;messages=[];messageText='';chatSeq++"><p>仅双方可见 · 每5秒检查会话与订单状态</p><div class="messages"><article v-for="m in messages" :key="m.id"><small>{{m.sender_name}} · {{m.created_at}}</small><p>{{m.content}}</p></article><p v-if="!messages.length">暂无消息。</p></div><p v-if="chat.readonly" role="status">订单已结束，会话只读。</p><form v-else class="search" @submit.prevent="send"><input aria-label="消息内容" v-model="messageText" required maxlength="1500" placeholder="沟通校内交接安排…"><button :disabled="busy">发送</button></form><p v-if="failed" class="inline-error">{{feedback}}</p></Modal>
</template>
